import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'
import { fileURLToPath, URL } from 'node:url'
import { buildRobotsTxt } from './src/shared/seo/robots.js'

/**
 * Emits robots.txt into the build and serves it in `vite dev`.
 *
 * It is generated rather than committed because the `Sitemap:` line needs the
 * production origin, which comes from VITE_SITE_URL at build time. The rules
 * themselves live in `src/shared/seo/robots.js`.
 *
 * The sitemap itself is not built here: it is generated by the API from live
 * records (`GET /sitemap.xml`) and proxied through the rewrite in vercel.json,
 * so content added by an admin appears without a redeploy.
 */
const seoFiles = () => {
  let siteUrl = ''

  return {
    name: 'seo-files',
    configResolved(config) {
      siteUrl = config.env.VITE_SITE_URL || ''
      if (!siteUrl && config.command === 'build') {
        config.logger.warn(
          '[seo] VITE_SITE_URL is not set: robots.txt will omit its Sitemap line and canonical/OG URLs will be left out.',
        )
      }
    },
    configureServer(server) {
      server.middlewares.use('/robots.txt', (_req, res) => {
        res.setHeader('Content-Type', 'text/plain; charset=utf-8')
        res.end(buildRobotsTxt(siteUrl))
      })
    },
    generateBundle() {
      this.emitFile({
        type: 'asset',
        fileName: 'robots.txt',
        source: buildRobotsTxt(siteUrl),
      })
    },
  }
}

// https://vite.dev/config/
export default defineConfig({
  plugins: [react(), tailwindcss(), seoFiles()],
  resolve: {
    alias: {
      '@': fileURLToPath(new URL('./src', import.meta.url)),
    },
  },
  build: {
    // Splitting the vendor code keeps the main bundle from growing past the
    // point where a slow connection delays first render.
    rollupOptions: {
      output: {
        manualChunks: {
          react: ['react', 'react-dom', 'react-router-dom'],
          icons: ['react-icons/hi2'],
        },
      },
    },
  },
})
